window.__code__["code-w07-audit-middleware-py"] = {"code_id": "code-w07-audit-middleware-py", "kind": "local", "title": "audit_middleware.py", "source_path": "/Users/zhongyou/Desktop/2027年/code/w07/audit_middleware.py", "highlight_line": null, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># code/w07/audit_middleware.py</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\"><span class=\"c-com\"># W07 作业1:写一个审计中间件,记录每次推理的迭代号 + token 用量</span></span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\"><span class=\"c-com\"># 体会:不动 Agent 源码就给它加行为——洋葱模型 hook</span></span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\"><span class=\"c-com\"># 前置: export DASHSCOPE_API_KEY=\u00004\u0000</span></span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\"><span class=\"c-com\"># 运行:  python code/w07/audit_middleware.py</span></span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\"><span class=\"c-com\"># 预期:  每轮推理前后打印 [audit] 行,含迭代号和 token 用量</span></span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\"><span class=\"c-com\"># ============================================================</span></span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\"><span class=\"c-kw\">import</span> asyncio</span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\"><span class=\"c-kw\">import</span> os</span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\"><span class=\"c-kw\">from</span> typing <span class=\"c-kw\">import</span> AsyncGenerator, Callable</span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.agent <span class=\"c-kw\">import</span> Agent</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.credential <span class=\"c-kw\">import</span> DashScopeCredential</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.message <span class=\"c-kw\">import</span> UserMsg</span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.middleware <span class=\"c-kw\">import</span> MiddlewareBase</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.model <span class=\"c-kw\">import</span> DashScopeChatModel</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\"><span class=\"c-kw\">from</span> agentscope.tool <span class=\"c-kw\">import</span> Bash, Toolkit</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\"><span class=\"c-kw\">class</span> AuditMiddleware(MiddlewareBase):</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;记录每次推理的迭代号与 token 用量。&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_reasoning(</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">        agent: Agent,</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">        input_kwargs: dict,</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">        next_handler: Callable[[], AsyncGenerator],</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">    ) -&gt; AsyncGenerator:</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">        <span class=\"c-com\"># 前处理:打印迭代号</span></span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">        print(f<span class=\"c-str\">&quot;  📝 [audit] reasoning iter={agent.state.cur_iter}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">        <span class=\"c-com\"># 调下一层洋葱(真正的推理),把事件透传给上层</span></span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">        <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> item <span class=\"c-kw\">in</span> next_handler():</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">            <span class=\"c-kw\">yield</span> item</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">        <span class=\"c-com\"># 后处理:看最后一条消息的 token 用量</span></span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">        last = agent.state.context[-1] <span class=\"c-kw\">if</span> agent.state.context <span class=\"c-kw\">else</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">        usage = getattr(last, <span class=\"c-str\">&quot;usage&quot;</span>, <span class=\"c-kw\">None</span>) <span class=\"c-kw\">if</span> last <span class=\"c-kw\">else</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">        print(f<span class=\"c-str\">&quot;  📝 [audit] done usage={usage}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\"><span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> main() -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">    model = DashScopeChatModel(</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">        credential=DashScopeCredential(api_key=os.environ[<span class=\"c-str\">&quot;DASHSCOPE_API_KEY&quot;</span>]),</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">        model=<span class=\"c-str\">&quot;qwen-plus&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">        stream=<span class=\"c-kw\">True</span>,</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">    )</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\">    agent = Agent(</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">        name=<span class=\"c-str\">&quot;audit&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">        system_prompt=<span class=\"c-str\">&quot;你是助手&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">        model=model,</span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">        toolkit=Toolkit(tools=[Bash()]),</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">        middlewares=[AuditMiddleware()],  <span class=\"c-com\"># plug 进去</span></span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">    )</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> e <span class=\"c-kw\">in</span> agent.reply_stream(UserMsg(<span class=\"c-str\">&quot;u&quot;</span>, <span class=\"c-str\">&quot;看下当前目录有哪些文件&quot;</span>)):</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> e.type.value == <span class=\"c-str\">&quot;TEXT_BLOCK_DELTA&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">            print(e.delta, end=<span class=\"c-str\">&quot;&quot;</span>, flush=<span class=\"c-kw\">True</span>)</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">    print()</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\"><span class=\"c-kw\">if</span> __name__ == <span class=\"c-str\">&quot;__main__&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">    asyncio.run(main())</span></div>\n</div>", "lines": 61, "explanation": "audit_middleware.py 是本教程的可运行示例代码，示范对应周次核心概念；顶部注释含运行前置依赖与预期输出，建议结合左侧源码与对应周文档「动手作业」一起读。", "knowledge_points": [], "related_docs": ["W07-中间件记忆与上下文治理"]};
